@sig trait PreparationAssessment_Api {
  def id: Art.BridgeId
  def preparation_observation_Id : Art.PortId
  def preparation_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var preparation_facts: EIT_Acquisition_Supervisor.PreparationFacts.Type = $

  def put_preparation_facts(value : EIT_Acquisition_Supervisor.PreparationFacts.Type) : Unit = {
    Contract(
      Modifies(preparation_facts),
      Ensures(
        preparation_facts == value
      )
    )
    Spec {
      preparation_facts = value
    }

    Art.putValue(preparation_facts_Id, EIT_Acquisition_Supervisor.PreparationFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PreparationAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val preparation_observation_Id : Art.PortId,
  val preparation_facts_Id : Art.PortId) extends PreparationAssessment_Api

@datatype class PreparationAssessment_Operational_Api (
  val id: Art.BridgeId,
  val preparation_observation_Id : Art.PortId,
  val preparation_facts_Id : Art.PortId) extends PreparationAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var preparation_observation: EIT_Acquisition_Supervisor.PreparationObservation.Type = $

  def get_preparation_observation() : Option[EIT_Acquisition_Supervisor.PreparationObservation.Type] = {
    Contract(
      Ensures(
        Res == Some(preparation_observation)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.PreparationObservation.Type] = Art.getValue(preparation_observation_Id) match {
      case Some(EIT_Acquisition_Supervisor.PreparationObservation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port preparation_observation.  Expecting 'EIT_Acquisition_Supervisor.PreparationObservation_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.PreparationObservation.Type]()
      case _ => None[EIT_Acquisition_Supervisor.PreparationObservation.Type]()
    }
    return value
  }
}
